import re
import unicodedata
from html import unescape

def fix_text(text: str) -> str:
    """Given a possibly-corrupted Unicode string, return a repaired,
    normalized version of the same text."""

    def decode_mojibake(s):
        encodings = ['windows-1252', 'latin-1']
        for enc in encodings:
            try:
                s_bytes = s.encode(enc)
                decoded = s_bytes.decode('utf-8')
                if decoded != s:
                    return decoded
            except UnicodeEncodeError:
                continue
        return s

    def remove_control_chars(s):
        return ''.join(c for c in s if unicodedata.category(c)[0] != 'C')

    def normalize_line_endings(s):
        return s.replace('\r\n', '\n').replace('\r', '\n').replace('\u2028', '\n').replace('\u2029', '\n')

    def convert_fullwidth(s):
        return ''.join(chr(ord(c) - 0xFEE0) if '\uff01' <= c <= '\uff5f' else c for c in s)

    def normalize_nfc(s):
        return unicodedata.normalize('NFC', s)

    # Rule 5 & 6: Decode HTML entities
    text = unescape(text)

    # Rule 7 & 8: Remove control characters while preserving legitimate whitespace
    text = remove_control_chars(text)

    # Rule 12: Convert full-width punctuation and spaces to standard counterparts
    text = convert_fullwidth(text)

    # Rule 13: Normalize line endings
    text = normalize_line_endings(text)

    # Rule 10 & 11: Normalize to NFC
    text = normalize_nfc(text)

    # Rule 1 & 2: Correct mojibake by decoding and re-encoding
    prev_text = None
    while prev_text != text:
        prev_text = text
        text = decode_mojibake(text)

    return text
